// Pusat Bantuan Aplikasi AMU Service.
// Panduan disaring berdasarkan peran, tetapi admin/super admin dapat melihat seluruh topik.
import { $, esc } from './util.js';
import { st, views, refreshers, actions } from './state.js';
import { APP_VERSION } from './config.js';

const P = {
  baru: { pendek: 'Apa yang baru ✨', judul: 'Apa yang baru — versi 5.19.0', ringkas: 'Ringkasan lengkap perubahan versi 5.19.0: tampilan modern bergradasi, Chat gaya messenger dengan status Online/Sibuk/Offline, dan loading yang jauh lebih ringan. Baca bagian ini dulu setelah aplikasi diperbarui.', bagian: [
    ['Cara memastikan sudah memakai versi 5.19.0', 'Lihat tulisan kecil <b>versi 5.19.0</b> di bagian bawah bilah kiri (atau di halaman login sisi kiri bawah). Jika masih tertulis versi lama, tekan <b>Update aplikasi</b> di bilah kiri bawah (atau di layar login). Tombol ini sekarang mengosongkan salinan aplikasi lama di perangkat, mengambil versi terbaru, lalu memuat ulang halaman secara otomatis dalam ±3 detik. Data transaksi tidak ikut terhapus.'],
    ['Ringkasan perubahan', '<b>1. Tampilan baru "Aurora":</b> bilah kiri dan bilah atas memakai gradasi warna yang menyambung dari kiri ke kanan, kartu dan tombol lebih bulat, huruf Plus Jakarta Sans yang lebih mudah dibaca, ikon di setiap menu, dan kartu sapaan bergradasi di Beranda. <b>2. Chat Internal baru:</b> tampilan dua kolom seperti aplikasi pesan, status <b>Online (live) / Sibuk / Offline</b> setiap petugas, penanda pesan belum dibaca per percakapan, pemisah tanggal, Enter untuk kirim, dan bisa chat pribadi dengan Super Admin. <b>3. Loading lebih ringan:</b> aplikasi dibuka dari salinan di perangkat, data dimuat bersamaan, dan menu yang dibuka ulang tidak mengunduh data yang sama berkali-kali.'],
    ['Tombol status di bilah atas', 'Di kanan atas sekarang ada tombol bulat bertuliskan <b>Online</b> dengan titik hijau. Klik untuk memilih <b>Online</b> (siap membalas), <b>Sibuk</b> (sedang melayani konsumen/tidak bisa membalas cepat), atau <b>Offline</b> (tampil offline untuk petugas lain). Titik kecil di foto profil Anda ikut berubah warna. Lihat topik <b>Chat & Status</b> untuk penjelasan lengkap.'],
    ['Kartu sapaan di Beranda', 'Bagian paling atas Beranda menampilkan salam sesuai jam (pagi/siang/sore/malam), nama Anda, tanggal lengkap, ringkasan hari ini (omzet dan jumlah motor di bengkel, bila peran Anda boleh melihatnya), serta maksimal empat tombol pintas: <b>Motor masuk</b>, <b>Jual part</b>, <b>Pembayaran</b>, <b>Cek stok</b>, atau <b>Chat</b>. Tombol pintas hanya muncul untuk menu yang memang boleh Anda buka.'],
    ['Apa yang lebih cepat', '<b>Membuka aplikasi:</b> file aplikasi tidak lagi diunduh satu per satu dari internet setiap kali dibuka; versi baru diunduh diam-diam di belakang layar. <b>Setelah login:</b> data cabang, hak akses, dan data petugas dibaca bersamaan. Aplikasi terbuka paling lama ±3,5 detik walau sinyal lemah; data yang belum datang akan langsung mengisi layar begitu tiba. <b>Menu yang sering dibuka:</b> daftar petugas dan data nota periode lama (Laporan, Performa Mekanik, Klaim KSG, Penghasilan) disimpan sementara 60 detik, sehingga berpindah menu lalu kembali terasa instan. <b>Chat:</b> pesan sudah terunduh sejak login, jadi Chat langsung tampil tanpa loading.'],
    ['Apakah ada yang berubah pada cara kerja transaksi?', 'Tidak. Registrasi, order part, pembayaran, stok, kas, retur, absensi, penghasilan, dan laporan bekerja sama seperti sebelumnya. Perubahan hanya pada tampilan, Chat, dan cara data dimuat. Semua tombol, menu, dan hak akses tetap di tempat yang sama.'],
    ['Yang perlu dilakukan Super Admin setelah update', '<b>1.</b> Publish ulang <b>firestore.rules</b> (berisi aturan baru koleksi <code>presence</code> untuk status Online/Sibuk/Offline). Tanpa ini aplikasi tetap jalan, tetapi semua petugas akan terlihat Offline. <b>2.</b> Deploy <b>firestore.indexes.json</b> (dua index baru untuk koleksi <code>chat</code>) supaya pesan selalu diambil dari yang terbaru. Tanpa index, Chat otomatis memakai cara lama sehingga tetap berfungsi. <b>3.</b> Minta semua perangkat menekan <b>Update aplikasi</b> sekali.']
  ]},
  chat: { pendek: 'Chat & Status', judul: 'Chat Internal & Status Online', ringkas: 'Cara memakai Chat Internal 5.19.0: ruang Umum, chat pribadi (termasuk dengan Super Admin), status Online/Sibuk/Offline, penanda belum dibaca, notifikasi suara, mode pantau dan transkrip Super Admin.', bagian: [
    ['Siapa yang bisa membuka Chat?', 'Chat Internal muncul di menu kiri bagian <b>Komunikasi</b> hanya bila Super Admin mencentang <b>Chat Internal</b> untuk peran Anda di <b>Master Data → Hak Akses Menu</b>. Super Admin selalu dapat membuka Chat. Jika menu Chat tidak terlihat, minta Super Admin memberi akses lalu tekan <b>Update aplikasi</b> atau muat ulang halaman.'],
    ['Mengenal layar Chat', 'Layar Chat terbagi dua. <b>Kolom kiri</b> berisi judul <b>Chat</b> dan jumlah petugas yang sedang online, kotak <b>Cari petugas atau cabang</b>, lalu daftar percakapan: <b>Umum · semua petugas</b> di paling atas, kelompok <b>Percakapan</b> (petugas yang pernah Anda ajak chat, urut dari pesan terbaru), dan kelompok <b>Petugas</b> (yang belum pernah diajak chat, urut dari yang online). <b>Kolom kanan</b> menampilkan isi percakapan yang dipilih, dengan kepala berisi nama, status, peran, dan cabang lawan bicara. Di HP, daftar dan isi percakapan tampil bergantian: ketuk nama untuk membuka, ketuk tombol <b>‹</b> di kiri atas untuk kembali ke daftar.'],
    ['Ruang Umum', 'Klik <b>Umum · semua petugas</b>. Pesan di sini terlihat oleh semua petugas yang memiliki akses Chat di semua cabang. Gunakan untuk pengumuman, koordinasi stok, atau informasi motor selesai. Kepala percakapan menampilkan jumlah petugas online dan foto inisial beberapa petugas yang sedang online.'],
    ['Chat pribadi', 'Klik nama petugas di kolom kiri. Pesan pribadi hanya dapat dibaca oleh Anda dan petugas tersebut (Super Admin dapat membaca untuk audit). Chat pribadi bisa antarpetugas satu cabang maupun lintas cabang. Mulai 5.19.0 tersedia juga kontak <b>Super Admin</b> sehingga petugas dapat bertanya langsung kepada pemilik.'],
    ['Mengirim pesan', 'Ketik di kotak <b>Tulis pesan…</b> di bawah. Tekan <kbd>Enter</kbd> atau tombol kirim bulat untuk mengirim. Tekan <kbd>Shift</kbd>+<kbd>Enter</kbd> untuk membuat baris baru. Kotak tulisan membesar otomatis untuk pesan panjang (maksimal 2.000 karakter). Huruf ditulis apa adanya (tidak diubah menjadi kapital). Jika muncul pesan <i>gagal dikirim</i>, teks Anda dikembalikan ke kotak tulisan sehingga dapat dikirim ulang.'],
    ['Membaca percakapan', 'Pesan Anda tampil di kanan dengan gelembung bergradasi. Pesan orang lain tampil di kiri dengan inisial, nama, peran, dan cabang pengirim. Pesan berurutan dari orang yang sama dalam 5 menit digabung agar rapi. Pemisah <b>Hari ini</b>, <b>Kemarin</b>, atau tanggal lengkap memudahkan mencari pesan lama. Jam kirim tampil di pojok gelembung; arahkan kursor ke jam untuk melihat tanggal dan jam lengkap.'],
    ['Status Online, Sibuk, Offline', 'Setiap petugas memiliki titik status: <b>hijau = Online</b> (aplikasi sedang terbuka dan siap membalas; di kepala percakapan tertulis <b>Online · live</b> dengan titik berkedip), <b>oranye = Sibuk</b> (sedang melayani, balasan mungkin lambat), <b>abu-abu = Offline</b> (aplikasi tidak dibuka, atau petugas memilih tampil offline). Untuk petugas offline ditampilkan keterangan seperti <i>aktif 12 menit lalu</i>.'],
    ['Mengganti status Anda', 'Klik tombol status di kanan atas (bertuliskan Online/Sibuk/Offline). Pilih status yang sesuai. Pilihan Anda diingat di perangkat ini dan dikirim ke server, sehingga petugas lain langsung melihatnya saat membuka Chat. Di HP, tombol status hanya menampilkan titik warna untuk menghemat tempat.'],
    ['Bagaimana status dihitung otomatis', 'Selama aplikasi terbuka dan layarnya terlihat, perangkat mengirim tanda aktif kecil setiap 2,5 menit memakai jam server (jam HP yang salah tidak memengaruhi). Jika tidak ada tanda aktif lebih dari <b>6 menit</b> (misalnya aplikasi ditutup, HP terkunci, atau tab disembunyikan), status Anda otomatis menjadi <b>Offline</b>. Saat Anda menekan <b>Keluar</b> atau menutup halaman, status langsung diubah ke Offline. Ketika aplikasi dibuka lagi, status kembali sesuai pilihan terakhir Anda.'],
    ['Penanda belum dibaca', 'Angka bulat di samping menu <b>Chat Internal</b> (bilah kiri) adalah total pesan belum dibaca dari ruang Umum dan chat pribadi Anda. Di dalam Chat, setiap percakapan memiliki angka sendiri, nama dan cuplikan pesannya tampil tebal. Pesan dianggap dibaca ketika percakapan tersebut dibuka. Penanda baca disimpan per perangkat; membuka Chat di HP tidak menghapus angka di PC.'],
    ['Notifikasi suara', 'Centang <b>Bunyi notifikasi pesan baru</b> di bawah kolom kiri untuk mendengar bunyi pendek setiap ada pesan masuk dari orang lain (ruang Umum atau chat pribadi Anda), walau Anda sedang membuka menu lain. Hilangkan centang untuk mematikan. Pengaturan ini berlaku per perangkat dan diingat walau aplikasi ditutup.'],
    ['Mencari petugas', 'Ketik nama, peran, atau nama cabang di kotak <b>Cari petugas atau cabang</b>. Daftar langsung tersaring. Hapus tulisan untuk melihat semua kembali.'],
    ['Aturan penggunaan chat', 'Pesan adalah <b>log permanen</b>: tidak dapat diedit atau dihapus oleh siapa pun, termasuk Super Admin. Tulis dengan sopan dan jelas. Jangan mengirim PIN, kata sandi, NIK lengkap, atau data pribadi konsumen yang tidak perlu. Untuk keputusan resmi (pembatalan nota, retur, perubahan stok) tetap gunakan menu dan alur persetujuan aplikasi; chat hanya untuk koordinasi.'],
    ['Mode pantau Super Admin', 'Super Admin melihat kelompok tambahan <b>Pantau percakapan petugas</b> berisi chat pribadi antarpetugas lain (judul <i>Nama A ↔ Nama B</i>, ikon mata). Percakapan ini hanya dapat dibaca; kotak tulisan diganti keterangan <b>Mode pantau</b>. Pesan pantauan tidak dihitung sebagai belum dibaca.'],
    ['Transkrip Excel (Super Admin)', 'Tombol <b>⬇ Excel</b> di kolom kiri atas hanya tampil untuk Super Admin. File berisi kolom Waktu, Ruang, Lawan, Pengirim, Peran, Cabang, dan Pesan, lengkap dengan garis kotak dan filter, diurutkan dari pesan terlama. Maksimal 5.000 pesan terakhir per unduhan.'],
    ['Berapa banyak pesan yang ditampilkan?', 'Agar tetap ringan, Chat memuat 300 pesan Umum terbaru dan 500 pesan pribadi terbaru (Super Admin: 600). Pesan yang lebih lama tetap tersimpan permanen di database dan ikut terunduh dalam transkrip Excel Super Admin.']
  ]},
  tampilan: { pendek: 'Tampilan', judul: 'Tampilan, navigasi & kecepatan', ringkas: 'Penjelasan lengkap bagian-bagian layar 5.19.0, cara berpindah menu, tema dan mode gelap, foto profil, cabang, memasang aplikasi, memperbarui aplikasi, serta cara kerja loading data.', bagian: [
    ['Bagian-bagian layar', '<b>Bilah kiri (sidebar)</b>: nama toko, daftar menu yang dikelompokkan (Utama, Komunikasi, Bengkel, Sparepart, Kasir, Keuangan, Pengaturan, Akun Saya, Bantuan), lalu bagian bawah berisi nama dan peran Anda, tombol <b>Ganti PIN</b>, <b>Keluar</b>, <b>Pasang aplikasi</b>, <b>Update aplikasi</b>, <b>Mode gelap/terang</b>, dan nomor versi. <b>Bilah atas</b>: tombol menu (☰), judul halaman, pilihan cabang (admin) atau nama cabang, tombol status, foto profil, serta jam. <b>Bilah tombol cepat</b>: tombol F1/F2/F3/F8 yang hanya muncul bila berguna di halaman itu. <b>Area kerja</b>: isi menu yang sedang dibuka.'],
    ['Gradasi warna bilah kiri dan atas', 'Bilah kiri berwarna gradasi dari atas ke bawah, dan bilah atas melanjutkan warna tersebut dari kiri ke kanan sehingga keduanya tampak menyatu. Warna gradasi mengikuti tema yang dipilih Super Admin (Biru Segar, Biru Klasik, Hijau Tosca, Ungu, Merah Marun, Gelap, atau Kaca). Kartu sapaan Beranda, gelembung chat Anda, tombol utama, dan garis warna di atas kartu ringkasan memakai warna yang sama.'],
    ['Ikon menu dan menu aktif', 'Setiap menu memiliki ikon garis agar mudah dikenali. Menu yang sedang dibuka tampil sebagai kartu putih terang di bilah kiri. Angka bulat kuning di samping menu (mis. Persetujuan, Chat, Cek Stok) menandakan ada hal yang perlu ditindaklanjuti.'],
    ['Menyembunyikan dan membuka menu', 'Di PC/laptop, tekan tombol <b>☰</b> di kiri atas untuk menyembunyikan bilah kiri agar area kerja lebih lebar; tekan lagi untuk menampilkan. Pilihan ini diingat di perangkat. Di HP, bilah kiri tersembunyi; tekan <b>☰</b> untuk membuka, lalu pilih menu atau ketuk area gelap untuk menutup.'],
    ['Mode gelap dan tema', 'Tombol <b>☾ Mode gelap</b> / <b>☀ Mode terang</b> di bilah kiri bawah (dan di layar login) mengganti tampilan di perangkat Anda saja. Tema warna untuk semua perangkat dipilih Super Admin di <b>Master Data → Tema Tampilan</b>. Tema <b>Otomatis</b> mengikuti mode gelap/terang HP atau PC. Tema <b>Kaca</b> paling berat untuk PC/HP lama; pilih tema lain bila perangkat terasa lambat.'],
    ['Foto profil', 'Klik foto/inisial Anda di kanan atas, pilih foto dari galeri atau kamera. Foto diperkecil otomatis lalu disimpan. Titik kecil di sudut foto menunjukkan status Anda (hijau Online, oranye Sibuk, abu-abu Offline).'],
    ['Berpindah cabang (admin)', 'Admin dan Super Admin melihat pilihan <b>Cabang</b> di bilah atas bila ada lebih dari satu cabang. Memilih cabang lain mengganti data yang tampil (stok, WO, nota, pembelian) dan mengosongkan draf yang belum disimpan milik cabang sebelumnya. Petugas lain hanya melihat nama cabangnya sendiri.'],
    ['Memasang aplikasi di HP / PC', 'Tekan <b>Pasang aplikasi</b> (bilah kiri bawah atau layar login) bila tombolnya muncul. Di iPhone/iPad: buka di Safari, ketuk tombol Bagikan, pilih <b>Tambah ke Layar Utama</b>. Setelah terpasang, aplikasi terbuka tanpa bilah alamat browser dan lebih cepat dibuka.'],
    ['Memperbarui aplikasi', 'Versi baru biasanya terpasang otomatis pada pembukaan berikutnya. Jika setelah pengumuman update tampilan masih lama, tekan <b>Update aplikasi</b>. Aplikasi mengosongkan salinan lama di perangkat, mengambil versi terbaru, lalu memuat ulang sendiri (paling lama ±3 detik). Login dan data tidak hilang.'],
    ['Cara kerja loading 5.19.0', '<b>File aplikasi</b> dibuka dari salinan di perangkat (instan) dan diperbarui di belakang layar. <b>Halaman utama</b> tetap dicek ke internet dulu maksimal 2,5 detik agar update terdeteksi. <b>Data</b> (nota hari ini, WO, part, pengaturan) dipantau realtime: aplikasi terbuka setelah data siap atau paling lama ±3,5 detik, sisanya langsung mengisi layar ketika datang. <b>Master jasa & mekanik</b> ditampilkan dari salinan di perangkat dulu, lalu diperbarui dari server. <b>Data periode lama</b> dan <b>daftar petugas</b> disimpan sementara 60 detik di memori; perubahan nota hari ini membersihkan simpanan nota secara otomatis.'],
    ['Animasi loading', 'Animasi roda gigi hanya muncul bila data benar-benar perlu ditunggu (lebih dari ±0,2 detik). Jika data sudah ada di perangkat, layar langsung tampil tanpa berkedip. Bila roda gigi berputar lebih dari 15 detik, lihat topik <b>Aplikasi loading terus</b> di Masalah umum & solusi.'],
    ['Tips agar aplikasi tetap ringan', 'Tutup tab aplikasi yang ganda (cukup satu tab /pos per perangkat). Pasang aplikasi ke layar utama. Gunakan tema selain Kaca di perangkat lama. Pada Laporan, pilih rentang tanggal secukupnya (harian/bulanan) daripada rentang sangat panjang. Di Stok Part, gunakan pencarian/filter daripada menggulir ribuan baris. Tekan Update aplikasi hanya bila diminta atau bila tampilan tidak berubah setelah pengumuman update.']
  ]},
  menu: { pendek: 'Fungsi menu', judul: 'Fungsi setiap menu', ringkas: 'Daftar lengkap seluruh menu aplikasi: kegunaan, peran yang biasanya dapat membuka, dan fungsi utama di dalamnya. Menu yang tampil pada akun Anda dapat dibatasi Super Admin melalui Hak Akses Menu.', bagian: [
    ['Beranda', '<b>Peran bawaan:</b> Admin, Registrasi, Sparepart, Kasir, Service Advisor. <b>Fungsi:</b> kartu sapaan dan tombol pintas; kotak ringkasan <b>Omzet hari ini</b>, <b>Part terjual</b>, <b>Motor masuk bengkel</b>, <b>Stok menipis</b> (kotak yang tampil per peran diatur Super Admin); grafik omzet 7 hari (klik batang untuk melihat nota hari itu); <b>Status mekanik</b>; <b>Antrian bengkel</b> (klik motor untuk membuka pembayaran atau riwayat); <b>Perlu dipesan ulang</b>. Klik setiap kotak untuk melihat rinciannya.'],
    ['Persetujuan', '<b>Peran:</b> Admin/Super Admin. <b>Fungsi:</b> daftar hal yang menunggu keputusan: <b>Pembatalan nota</b>, <b>Stok opname</b>, dan <b>Aktivasi layar QR absen</b>. Tombol <b>Periksa</b>, <b>Setujui</b>, <b>Tolak</b>, atau <b>Cabut</b>. Angka di menu menunjukkan jumlah yang menunggu.'],
    ['Chat Internal', '<b>Peran:</b> sesuai centang Hak Akses Menu (Super Admin selalu). <b>Fungsi:</b> ruang Umum, chat pribadi lintas cabang, status Online/Sibuk/Offline, penanda belum dibaca, notifikasi suara, transkrip Excel (Super Admin). Lihat topik <b>Chat & Status</b>.'],
    ['Registrasi Servis', '<b>Peran:</b> Admin, Registrasi. <b>Fungsi:</b> menerima motor masuk, mencari data konsumen lama, data KTP/STNK, KM, keluhan, pilihan KSB/KSG, mekanik, nomor antrean, nomor cepat saat ramai, rincian jasa/part/biaya lainnya, BAST kendaraan, menerima laporan selesai/tunda dari mekanik, membatalkan pendaftaran.'],
    ['Konsumen & Kendaraan', '<b>Peran:</b> Admin, Registrasi. <b>Fungsi:</b> daftar konsumen dan motornya, <b>+ Konsumen baru</b>, <b>Tambah motor</b>, ubah data, tandai <b>Perlu dicek</b>, <b>Gabungkan</b> konsumen ganda, <b>Pindahkan</b> motor ke pemilik lain, hapus data pribadi atas permintaan, serta <b>Daftar & Cetak</b> berdasarkan periode.'],
    ['Riwayat Kendaraan', '<b>Peran:</b> Admin, Registrasi, Kasir, Sparepart, Service Advisor. <b>Fungsi:</b> cari nomor polisi untuk melihat data kendaraan, pemilik, servis yang sedang berjalan, dan seluruh riwayat servis; klik baris untuk rincian jasa, part, dan biaya. Plat yang sudah berganti otomatis diarahkan ke plat baru.'],
    ['Pengingat Servis', '<b>Peran:</b> Admin, Registrasi, Kasir. <b>Fungsi:</b> daftar jadwal ganti oli berikutnya, tombol <b>WA ingatkan</b>, <b>Tunda 14 hari</b>, <b>Ganti di luar</b>, <b>Stop</b>/<b>Aktifkan lagi</b>, pengaturan jangka pengingat, dan <b>Bangun jadwal dari nota lama</b>.'],
    ['Order Sparepart', '<b>Peran:</b> Admin, Sparepart. <b>Fungsi:</b> memasukkan part yang dipakai untuk WO servis, memeriksa stok, menyimpan order agar muncul di Register dan Pembayaran.'],
    ['Pembayaran & Status Servis', '<b>Peran:</b> Admin, Kasir. <b>Fungsi:</b> daftar motor di bengkel, membuka WO berstatus Selesai, memeriksa total jasa/part/biaya/KSG, menerima cash/transfer, mencetak nota.'],
    ['Performa Mekanik', '<b>Peran:</b> Admin, Mekanik, Service Advisor. <b>Fungsi:</b> pekerjaan saat ini, motor selesai per periode, waktu servis, rata-rata waktu per tipe motor, rincian nilai pekerjaan, target dan pencapaian insentif.'],
    ['Cek Stok', '<b>Peran:</b> Admin, Registrasi, Kasir, Sparepart, Mekanik. <b>Fungsi:</b> mencari stok part di cabang sendiri dan cabang lain, <b>Minta kirim</b> dari cabang lain, melihat <b>Permintaan masuk</b> (Kirim/Tolak) dan menerima kiriman di Stok Part.'],
    ['Penjualan Sparepart', '<b>Peran:</b> Admin, Kasir. <b>Fungsi:</b> menjual part langsung atau membayar <b>Pesanan Part Pribadi</b> dari Sparepart, scan barcode/ketik kode, cash/transfer, cetak nota, serta pengajuan <b>Retur setelah pembayaran</b>.'],
    ['Pesanan Part Pribadi', '<b>Peran:</b> Admin, Sparepart. <b>Fungsi:</b> membuat pesanan part atas nama pemesan dan nomor HP, harga/diskon/Add Price per item, mencetak pesanan untuk cek konsumen, membatalkan sebelum bayar dengan alasan. Pembayaran tetap di menu Penjualan Sparepart milik Kasir.'],
    ['Stok Part', '<b>Peran:</b> Admin, Sparepart. <b>Fungsi:</b> daftar part dengan pencarian, filter kategori/stok menipis, urut kolom, ubah harga beli/jual/Add Price/minimum, tambah part, Import Excel, kartu stok (mutasi), transfer antar cabang dan BAST transfer, export data.'],
    ['Stok Opname', '<b>Peran:</b> Admin, Sparepart. <b>Fungsi:</b> <b>+ Mulai opname</b>, menghitung fisik per part, <b>Ajukan ke super admin</b>; Super Admin dapat <b>Setujui & sesuaikan stok</b> atau <b>Tolak</b>.'],
    ['Pembelian Stok', '<b>Peran:</b> Admin, Sparepart. <b>Fungsi:</b> mencatat pembelian dari supplier, menambah stok, harga beli, dan riwayat pembelian per cabang.'],
    ['Laporan Penjualan', '<b>Peran:</b> Admin, Kasir, Service Advisor. <b>Fungsi:</b> pilihan <b>Harian, Mingguan, Bulanan, Tahunan, Custom</b>; kotak Total omzet, Penjualan part, Jasa servis, Klaim KSG (klik untuk menyaring); omzet per cabang; part terlaris; daftar nota (buka nota untuk <b>Ajukan pembatalan</b>/retur sesuai hak akses); <b>Unduh laporan Excel</b> atau <b>PDF</b>.'],
    ['Kas & Pengeluaran', '<b>Peran:</b> Admin, Kasir. <b>Fungsi:</b> tab <b>Kas harian</b> (uang laci awal, cash masuk, setor/tarik bank, saldo laci yang diharapkan, <b>Tutup kas</b> dan modal besok) dan tab <b>Pengeluaran</b> (pengeluaran tunai/transfer).'],
    ['Klaim KSG', '<b>Peran:</b> Admin, Kasir. <b>Fungsi:</b> daftar servis KSG per bulan, nilai klaim ke main dealer, pencatatan pembayaran klaim.'],
    ['Insight Konsumen', '<b>Peran:</b> Admin. <b>Fungsi:</b> konsumen terbaik, kunjungan servis per hari/bulan, jenis servis, tipe motor, jenis kelamin, usia, wilayah (kabupaten/kecamatan), daftar perlu diingatkan servis, unduh Excel.'],
    ['Backup Data', '<b>Peran:</b> Super Admin. <b>Fungsi:</b> <b>⬇ Backup sekarang</b> (file seluruh koleksi) dan <b>Pulihkan dari backup</b> untuk data terpilih. Lakukan minimal seminggu sekali.'],
    ['Master Data', '<b>Peran:</b> Admin (sebagian tab khusus Super Admin). <b>Tab:</b> Jasa Servis, Tarif KSG, Mekanik, Rekening, Tipe Motor, Petugas & PIN, Layar TV, Cabang, Insentif & Potongan, Logo, Tema Tampilan, Hak Akses Menu, Riwayat Perubahan Konsumen, Log Aktivitas.'],
    ['Absensi Saya / Absensi Karyawan', '<b>Petugas:</b> tombol <b>Scan QR absen masuk/pulang</b>, selfie, dan riwayat absensi bulan berjalan. <b>Super Admin (Absensi Karyawan):</b> tab Harian, Rekap bulanan, Layar QR, HP terdaftar, dan Pengaturan.'],
    ['Penghasilan Saya / Penghasilan Karyawan', '<b>Petugas:</b> gaji pokok, insentif, uang hadir, potongan, slip gaji PDF, THR & bonus milik sendiri. <b>Super Admin:</b> rekap seluruh karyawan, <b>Kunci bulan</b> untuk menerbitkan slip, unduh Excel, THR & Bonus karyawan.'],
    ['Panduan Penggunaan', '<b>Peran:</b> semua (tidak dapat dimatikan). <b>Fungsi:</b> pusat bantuan ini, pencarian kata kunci lintas topik, dan tombol <b>Cetak</b>.']
  ]},
  sa: { judul: 'Service Advisor', ringkas: 'Panduan peran Service Advisor (pimpinan/head mekanik): memantau bengkel, performa mekanik, laporan, dan insentif per kategori.', bagian: [
    ['Tugas utama', 'Service Advisor memimpin dan mengawasi mekanik: memastikan antrean bergerak, kualitas pekerjaan, ketepatan waktu, dan membantu Register/Kasir bila ada kendala teknis. Halaman pertama setelah login adalah <b>Performa Mekanik</b>.'],
    ['Menu yang tersedia', 'Bawaan: <b>Beranda</b> (omzet, part terjual, motor & status mekanik), <b>Riwayat Kendaraan</b>, <b>Performa Mekanik</b>, <b>Laporan Penjualan</b>, <b>Absensi Saya</b>, <b>Penghasilan Saya</b>, dan <b>Panduan</b>. Chat tampil bila diberi akses oleh Super Admin.'],
    ['Memantau bengkel dari Beranda', 'Lihat <b>Status mekanik</b> (siapa sedang mengerjakan motor apa) dan <b>Antrian bengkel</b>. Klik motor untuk membuka riwayatnya. Bila motor antri terlalu lama, koordinasikan dengan Register untuk memilih mekanik yang kosong.'],
    ['Performa Mekanik', 'Pilih periode lalu mekanik. Periksa pekerjaan saat ini, jumlah motor selesai, waktu servis, rata-rata waktu per tipe motor, rincian nilai pekerjaan, dan target. Gunakan data ini untuk pembinaan, bukan untuk mengubah transaksi.'],
    ['Insentif Service Advisor', 'Sejak 5.12.0 insentif SA dipisah menjadi tiga item: <b>Sparepart</b>, <b>Jasa servis</b>, dan <b>Biaya lain</b>, masing-masing dapat memiliki persentase dan target sendiri yang diatur Super Admin di <b>Master Data → Insentif & Potongan</b>. Basisnya adalah transaksi servis mekanik di cabang yang Anda pegang, per kategori. Rinciannya terlihat di <b>Penghasilan Saya</b>.'],
    ['Laporan', 'Buka <b>Laporan Penjualan</b> untuk melihat omzet per periode. Klik kotak Penjualan part, Jasa servis, atau Klaim KSG untuk menyaring. SA tidak dapat membatalkan nota; laporkan kesalahan nota kepada Kasir/Admin.']
  ]},
  sales: { judul: 'Sales', ringkas: 'Panduan peran Sales: absensi, penghasilan (uang hadir & potongan), dan chat bila diberi akses.', bagian: [
    ['Menu yang tersedia', 'Peran Sales secara bawaan hanya membuka <b>Absensi Saya</b>, <b>Penghasilan Saya</b>, dan <b>Panduan</b>. Halaman pertama setelah login adalah Absensi. Chat Internal dan menu lain tampil hanya bila Super Admin memberikannya di Hak Akses Menu.'],
    ['Absensi', 'Saat tiba, buka <b>Absensi Saya</b> lalu tekan <b>📷 Scan QR absen masuk</b>; arahkan kamera ke QR di layar absensi cabang dan ikuti instruksi selfie. Saat pulang, tombol yang sama berubah menjadi <b>Scan QR absen pulang</b>. Bila diatur Super Admin, tanpa scan pulang uang hadir hari itu tidak dihitung. Izinkan kamera dan lokasi. Jika ganti HP, minta admin mereset perangkat.'],
    ['Penghasilan', 'Sales menerima uang hadir dan potongan absensi sesuai aturan Super Admin; tidak ada insentif penjualan bawaan. Buka <b>Penghasilan Saya</b> untuk melihat rincian dan slip yang sudah diterbitkan.'],
    ['Koordinasi', 'Bila diberi akses Chat, gunakan ruang Umum untuk informasi bersama dan chat pribadi untuk koordinasi dengan admin atau Super Admin. Atur status <b>Sibuk</b> saat sedang bertemu pelanggan.']
  ]},
  umum: { judul: 'Umum — semua pengguna', ringkas: 'Cara masuk, memahami tampilan, keamanan akun, tombol cepat, dan aturan dasar penggunaan.', bagian: [
    ['Cara masuk sebagai petugas', '<b>1.</b> Buka <b>www.amuservice.id/pos</b>. <b>2.</b> Pilih nama Anda. <b>3.</b> Masukkan PIN 6 angka. <b>4.</b> Tekan <b>Masuk</b>. Jangan memakai akun orang lain karena setiap registrasi, perubahan, pembayaran, stok, dan persetujuan dicatat atas nama akun yang sedang masuk.'],
    ['Cara masuk sebagai super admin', 'Super admin masuk memakai email dan kata sandi. Tindakan sensitif seperti membatalkan nota, menghapus data, mengubah data penting, atau menyetujui stok opname dapat meminta kata sandi lagi.'],
    ['Memahami tampilan aplikasi', 'Menu di bilah kiri (bergradasi warna, lengkap dengan ikon) adalah modul yang boleh dibuka oleh peran Anda. Bilah atas melanjutkan gradasi tersebut dan berisi judul halaman, cabang, tombol status Online/Sibuk/Offline, foto profil, dan jam. <b>Beranda</b> berisi kartu sapaan dan ringkasan. Angka bulat kuning di samping menu atau angka merah di kotak berarti ada pekerjaan yang perlu ditindaklanjuti. Menu <b>Panduan Penggunaan</b> membuka halaman bantuan ini. Penjelasan lengkap ada di topik <b>Tampilan</b> dan <b>Fungsi setiap menu</b>.'],
    ['Pencarian panduan', 'Ketik kata seperti <b>BAST</b>, <b>KSG</b>, <b>transfer</b>, <b>stok</b>, <b>nota</b>, <b>PIN</b>, atau <b>absensi</b> di kotak pencarian. Hasil akan menampilkan topik dan langkah yang mengandung kata tersebut. Hapus kata pencarian untuk melihat seluruh panduan yang tersedia bagi Anda.'],
    ['Tombol cepat keyboard', '<kbd>F1</kbd> membuat data baru, <kbd>F2</kbd> menyimpan atau mengirim, <kbd>F3</kbd> memfokuskan pencarian, <kbd>F8</kbd> membuka/cetak nota terakhir, dan <kbd>Esc</kbd> menutup dialog. Di HP, gunakan tombol yang tampil di layar.'],
    ['Konfirmasi tindakan penting', 'Baca dialog sebelum menyetujui. Konfirmasi digunakan untuk pembayaran, status selesai, tunda, transfer, penerimaan barang, stok opname, penghapusan, pembatalan nota, dan keluar akun. Jika ragu, tekan <b>Batal</b>.'],
    ['Menyimpan pekerjaan', 'Jika tombol masih bertuliskan <b>Simpan</b> atau berwarna kuning, perubahan belum masuk database. Tekan tombol simpan dan tunggu pesan berhasil. Jangan menutup halaman saat indikator masih menyimpan. Jika muncul pesan gagal, catat nomor dokumen dan laporkan ke admin.'],
    ['Keluar dan tombol kembali', 'Gunakan tombol <b>Keluar</b> di aplikasi. Tombol kembali HP/browser dapat menampilkan pilihan kembali ke menu, keluar, atau batal. Bila ada formulir yang belum disimpan, simpan dulu atau batalkan dengan sadar.'],
    ['Absensi saya', 'Buka <b>Absensi Saya</b>, tekan <b>📷 Scan QR absen masuk</b>, arahkan kamera ke QR di layar absensi bengkel, lalu ikuti instruksi selfie. QR berubah berkala dan biasanya hanya dapat dipakai di lokasi bengkel. Saat selesai bekerja, tombol yang sama menjadi <b>Scan QR absen pulang</b>; jangan lupa scan pulang karena dapat memengaruhi uang hadir. Jika ganti HP, minta admin/super admin mereset perangkat.'],
    ['Penghasilan saya', 'Menu <b>Penghasilan Saya</b> hanya menampilkan data Anda: gaji pokok, insentif sparepart/jasa/biaya lain, uang hadir, rincian BPJS dan potongan absensi, slip, THR, dan bonus yang sudah diterbitkan. Jika angka tidak sesuai, jangan mengubah sendiri; sampaikan periode dan bagian yang salah kepada admin.'],
    ['Cek servis konsumen', 'Konsumen dapat membuka <b>www.amuservice.id</b> memakai nomor polisi dan nomor HP yang terdaftar. Pastikan nomor HP benar agar link cek servis dan pengingat WhatsApp tidak salah penerima.'],
    ['Aturan keamanan data', 'Jangan membagikan PIN, kata sandi, data NIK, atau screenshot transaksi ke pihak yang tidak berkepentingan. Jangan menghapus atau mengubah data untuk memperbaiki kesalahan tanpa mengikuti alur koreksi. Semua perubahan penting dapat masuk log aktivitas.']
  ]},
  registrasi: { judul: 'Registrasi Servis', ringkas: 'Menerima motor, mencatat konsumen/kendaraan, membuat antrean, mengatur mekanik, BAST, dan menerima laporan selesai/tunda.', bagian: [
    ['Alur kerja singkat', '<b>Motor datang → cari data lama → isi konsumen/kendaraan → pilih KSB/KSG → pilih mekanik → simpan → nomor antrean tampil → mekanik bekerja → mekanik melapor ke Register → Register menekan Selesai/Tunda → BAST dan pembayaran diproses.</b>'],
    ['Membuat pendaftaran baru', 'Buka <b>Registrasi Servis → + Motor masuk</b> atau tekan <kbd>F1</kbd>. Isi data sesuai KTP dan STNK. Nomor polisi wajib diisi. Pilih tipe motor, isi KM, keluhan, jenis layanan, dan mekanik bila sudah tersedia. Tekan <kbd>F2</kbd> untuk menyimpan dan membuat nomor antrean.'],
    ['Mencari data konsumen lama', 'Tekan <kbd>F3</kbd> atau gunakan kotak <b>Pernah servis di sini?</b>. Cari dengan sebagian nomor polisi, nama, nomor HP, NIK, nomor rangka, atau nomor mesin. Klik <b>Pakai data</b> jika konsumen dan motor sama. Klik <b>Pakai konsumen</b> atau <b>Konsumen saja</b> jika konsumennya sama tetapi motornya berbeda. Periksa kembali semua data sebelum menyimpan.'],
    ['Data konsumen yang wajib diperiksa', 'Nama harus sesuai KTP. Isi NIK 16 angka bila tersedia, nomor HP/WA, tempat/tanggal lahir, jenis kelamin, pekerjaan, alamat, RT/RW, provinsi, kabupaten/kota, kecamatan, dan kelurahan. Salah nomor HP dapat membuat konsumen tidak menerima notifikasi atau membuka riwayat yang salah.'],
    ['Data kendaraan yang wajib diperiksa', 'Periksa nomor polisi, nama pemilik di STNK, tipe, tahun, warna, nomor rangka, nomor mesin, dan KM. Jika nama STNK sama dengan konsumen, biarkan pilihan <b>sama dengan konsumen</b>. Jika berbeda, hilangkan centang dan isi nama STNK.'],
    ['KM kendaraan', 'Aplikasi menampilkan KM terakhir. KM baru tidak boleh lebih kecil. Jika speedometer diganti atau di-reset, admin harus menyimpan dengan catatan alasan. Jangan menurunkan KM hanya agar pengingat servis berubah.'],
    ['Pilihan KSB dan KSG', 'Untuk pendaftaran baru, pilih <b>KSB</b> atau <b>KSG</b>. KSB adalah kartu service berkala. KSG adalah kartu service gratis dan wajib memilih <b>KSG ke-1, ke-2, ke-3, atau ke-4</b> serta nomor kupon/buku servis bila tersedia. Data WO lama Reguler tetap dapat dibuka untuk menjaga riwayat.'],
    ['Aturan KSG', 'Setelah memilih KSG, checklist jasa standar tidak ditampilkan dan jasa KSG otomatis dianggap gratis. Nilai klaim diambil dari <b>Master Data → Tarif KSG</b> sesuai tipe motor dan KSG ke-berapa. Part serta biaya/jasa tambahan yang memang bukan bagian KSG tetap terlihat dan dapat ditagihkan sesuai kebijakan bengkel.'],
    ['Rincian jasa dan part', 'Bagian <b>Jasa servis/Jasa lainnya</b> menunjukkan jasa yang dipilih. Bagian <b>Rincian part</b> menampilkan kode, nama, jumlah, stok, dan nilai part yang sudah di-order untuk motor tersebut. Jika part belum terlihat, pastikan bagian Sparepart sudah menyimpan order dengan nomor WO yang benar.'],
    ['BAST kendaraan', 'Pada Register KSB/KSG tersedia bagian <b>BAST kendaraan</b>. Isi estimasi selesai/pengambilan secara manual, tanggal, jam, dan keterangan. Kode BAST otomatis menjadi <b>KSB</b> atau <b>KSG1–KSG4</b> dan muncul di pojok kanan atas. Tekan <b>Preview BAST</b>, lalu <b>Print / Simpan PDF</b>. BAST dibawa konsumen saat mengambil kendaraan.'],
    ['Memilih mekanik', 'Pilih mekanik yang berstatus kosong. Mekanik yang sedang mengerjakan motor lain tidak dapat dipilih. Jika belum ada mekanik, simpan tanpa mekanik sehingga statusnya <b>Antri</b>. Saat mekanik kosong, buka motor antri, pilih mekanik, lalu tekan <b>Simpan perubahan</b>.'],
    ['Status motor', '<b>Antri</b> berarti menunggu mekanik. <b>Dikerjakan</b> berarti ada mekanik yang menangani. <b>Ditunda</b> berarti pekerjaan berhenti sementara dan mekanik kembali kosong. <b>Selesai</b> berarti laporan mekanik sudah diterima Register dan menunggu pembayaran. <b>Lunas</b> berarti pembayaran selesai.'],
    ['Menerima laporan mekanik', 'Mekanik melapor kepada Register, bukan Kasir. Pada motor berstatus Dikerjakan, Register memilih <b>Motor selesai</b> jika pengerjaan selesai atau mengisi alasan lalu memilih <b>Lanjut lama (tunda)</b>. Alasan tunda wajib, misalnya <i>tunggu part</i> atau <i>konsumen ambil besok</i>. Kedua pilihan membuat mekanik kosong. Motor selesai memicu pemanggilan nomor antrean di layar TV.'],
    ['Melanjutkan motor yang ditunda', 'Buka tab <b>Ditunda</b>, pilih motor, pilih mekanik yang kosong, lalu tekan <b>Lanjutkan dikerjakan</b>. Mekanik boleh sama atau berbeda. Aplikasi menyimpan waktu kerja masing-masing mekanik dan alasan tunda.'],
    ['Nomor cepat saat ramai', 'Jika antrean panjang, gunakan <b>Nomor cepat (cukup nopol)</b>. Nomor antrean langsung dibuat, tetapi motor diberi tanda <b>Data belum lengkap</b>. Lengkapi data sebelum pembayaran atau sebelum pekerjaan membutuhkan informasi teknis.'],
    ['Motor terdaftar dua kali', 'Satu nomor polisi hanya boleh mempunyai satu servis aktif. Jika muncul peringatan, jangan membuat pendaftaran kedua. Tekan <b>Buka servis</b> untuk memperbaiki WO yang sudah ada.'],
    ['Ganti plat atau pemilik', 'Jika kendaraan berganti nomor polisi, gunakan alur <b>Ganti nomor polisi</b> agar riwayat tetap tersambung. Jika motor sudah menjadi milik orang lain, pilih <b>Ganti pemilik</b> dan isi alasan setelah memeriksa STNK. Jika orang lain hanya mengantar, pilih <b>Hanya mengantar</b> agar pemilik tetap benar.'],
    ['Pengingat ganti oli', 'Buka <b>Pengingat Servis</b>. Tab <b>Perlu diingatkan</b> berisi motor yang sudah mencapai batas KM atau hari. Gunakan <b>WA ingatkan</b>. Jika konsumen sudah ganti oli di tempat lain, catat tanggal dan KM pada <b>Ganti di luar</b>. Gunakan <b>Tunda 14 hari</b> bila belum ingin diingatkan atau <b>Stop</b> bila motor sudah dijual/pindah.']
  ]},
  sparepartMaster: { judul: 'Sparepart, harga master, dan Import Excel', ringkas: 'Mengelola stok, harga dasar, Add Price pusat, dan import data part.', bagian: [
    ['Add Price master', 'Add Price diatur per part pada <b>Stok Part</b> oleh <b>Sparepart Pusat</b> atau <b>Super Admin</b>. Harga final = harga jual dasar + Add Price. Kasir hanya melihat harga dan menerima pembayaran; Kasir, Register, dan Sparepart Cabang tidak dapat mengubahnya. Perubahan berlaku untuk transaksi baru di semua cabang, sedangkan transaksi lama tetap memakai harga yang tersimpan.'],
    ['Import Excel', 'Import Excel hanya tersedia untuk Sparepart Pusat dan Super Admin. File dibaca berdasarkan seluruh baris yang memiliki kode part. Harga dasar dan stok dapat diperbarui sesuai pilihan import, tetapi persentase Add Price master tidak ditimpa oleh kolom Excel. Periksa jumlah part baru, diperbarui, dan tidak berubah sebelum menekan Import.'],
    ['File Excel terbaca sedikit', 'Jika aplikasi membaca hanya 1 part, periksa file asli: beberapa file export memang hanya menyimpan satu baris data walaupun tampilan spreadsheet menampilkan banyak baris kosong/format. Simpan ulang sebagai XLSX/CSV yang benar-benar berisi seluruh baris, lalu ulangi preview. Jangan menekan Import bila jumlah preview tidak wajar.']
  ]},
  kasir: { judul: 'Kasir', ringkas: 'Menerima pembayaran servis atau penjualan part, mencetak nota, mengelola kas, dan memantau klaim.', bagian: [
    ['Batas tugas Kasir', 'Kasir berfokus pada <b>klik bayar</b>: cash atau transfer. Tambahan biaya, jasa, part, diskon, jenis layanan, dan finalisasi pekerjaan dilakukan di Register sesuai alur bengkel. Kasir tidak menekan Selesai/Tunda untuk laporan mekanik.'],
    ['Membayar servis', 'Buka <b>Pembayaran & Status Servis</b>, pilih motor berstatus <b>Selesai</b>, periksa nama konsumen, nomor polisi, rincian jasa, part, biaya lain, diskon, total, dan jenis KSG/KSB. Pilih <b>Cash</b> atau <b>Transfer</b>, pilih rekening bila transfer, masukkan nominal, tekan <kbd>F2</kbd>, periksa dialog konfirmasi, lalu setujui.'],
    ['KSG saat pembayaran', 'Untuk KSG, jasa standar gratis untuk konsumen. Part dan biaya/jasa tambahan tetap masuk sesuai data Register. Periksa nilai total sebelum menerima uang. Jika jasa KSG masih muncul sebagai tagihan, hentikan pembayaran dan minta Register memperbaiki jenis servisnya.'],
    ['Nota pembayaran', 'Setelah pembayaran berhasil, nota dapat dicetak, diunduh PDF, atau dikirim melalui WhatsApp. Periksa nomor nota, nama, nomor polisi, total, metode bayar, dan link cek servis sebelum menyerahkan nota.'],
    ['Pembayaran cash', 'Hitung uang yang diterima, masukkan nominal sebenarnya, dan periksa kembalian. Jangan memasukkan nominal pas jika konsumen memberikan uang lebih. Uang cash setelah kembalian masuk perhitungan kas harian.'],
    ['Pembayaran transfer', 'Pastikan transfer benar-benar masuk ke rekening bengkel, pilih rekening yang sesuai, lalu simpan bukti bila prosedur cabang mewajibkan. Jangan menerima berdasarkan screenshot tanpa memeriksa mutasi atau konfirmasi yang sah.'],
    ['Pesanan part pribadi dari Sparepart', 'Bagian Sparepart membuka menu khusus <b>Pesanan Part Pribadi</b> (bukan Penjualan Sparepart milik Kasir). Menu ini hanya untuk input pesanan dan cetak cek; tidak menampilkan pilihan cash/transfer dan tidak dapat memproses pembayaran. Isi <b>Nama pemesan</b>, mengisi <b>Nama pemesan</b> dan <b>Nomor HP</b>, mencari part, memasukkan jumlah, lalu memeriksa harga dan stok. Tekan <b>Simpan pesanan & cetak cek</b>. Lembar cetak diberikan kepada konsumen untuk memeriksa nama part, jumlah, harga, dan total. Pesanan belum dibayar pada tahap ini; pembayaran dilakukan di menu Kasir.'] ,
    ['Pemeriksaan pesanan di Kasir', 'Kasir membuka menu khusus <b>Penjualan Sparepart</b>. Hanya menu ini yang menampilkan pembayaran. Kasir melihat bagian <b>Pesanan dari Sparepart</b> dan melihat bagian <b>Pesanan dari Sparepart</b>. Pilih <b>Periksa & bayar</b>, cocokkan barang fisik dengan lembar yang sudah dicek konsumen, lalu terima pembayaran cash atau transfer. Jika ada kesalahan, jangan bayar; tekan <b>Tidak sesuai</b>, isi alasan, dan pesanan kembali ke Sparepart untuk diperbaiki.'] ,
    ['Peringatan barang part pribadi', 'Gunakan bahasa yang jelas kepada konsumen: <b>Harap periksa kembali barang pesanan, nama part, jumlah, dan harganya. Setelah pembayaran dilakukan, barang yang sudah dibeli tidak dapat dikembalikan atau ditukar.</b> Jangan melanjutkan pembayaran sebelum konsumen menyatakan pesanannya sesuai.'] ,
    ['Kesalahan sebelum pembayaran', 'Jangan membayar WO yang salah. Kembali ke Register untuk memperbaiki data, jasa, part, biaya, atau jenis layanan. Setelah diperbaiki, muat ulang daftar pembayaran dan periksa total lagi.'],
    ['Pembatalan nota', 'Nota yang sudah dibayar tidak diedit langsung. Buka nota, pilih <b>Ajukan pembatalan</b>, tulis alasan rinci, lalu kirim untuk persetujuan super admin. Jangan membuat nota pengganti sebelum status pembatalan jelas.'],
    ['Kas harian dan pembelian', 'Pagi hari buka <b>Kas & Pengeluaran → Buka kas</b> dan isi uang awal. Setiap pembayaran servis dan part pribadi otomatis masuk ke transaksi kas: bagian <b>cash</b> menambah uang laci setelah memperhitungkan kembalian, sedangkan <b>transfer</b> langsung masuk rekening yang dipilih dan tidak menambah laci.'] ,
    ['Setor dan tarik uang bank', 'Saat menyetor uang laci ke bank, gunakan <b>Setor ke bank</b> atau isi setoran saat <b>Tutup kas</b>. Sistem mencatat uang laci berkurang dan mutasi bank bertambah. Jika mengambil uang dari bank untuk laci, gunakan <b>Tarik dari bank</b>; sistem mencatat bank berkurang dan laci bertambah. Periksa tanggal, jumlah, dan keterangan sebelum menyimpan.'] ,
    ['Pengeluaran', 'Buka tab <b>Pengeluaran</b>, isi tanggal, kategori, keterangan, nominal, dan sumber dana. Pilih <b>Tunai</b> jika uang diambil dari laci; pilih <b>Transfer / rekening</b> jika dibayar dari bank. Pengeluaran tunai mengurangi uang yang seharusnya ada di laci, sedangkan pengeluaran transfer tidak melewati laci.'] ,
    ['Klaim KSG', 'Buka <b>Klaim KSG</b>, pilih periode, periksa WO/nota KSG, centang dokumen yang diajukan, lalu kirim pengajuan. Saat pembayaran dari main dealer diterima, tekan <b>Tandai dibayar</b>, isi tanggal dan jumlah diterima. Sistem menandai nota dan otomatis mencatat penerimaan klaim sebagai <b>mutasi masuk bank</b>, bukan uang laci.']
  ]},
  mekanik: { judul: 'Mekanik', ringkas: 'Melihat pekerjaan, mengerjakan kendaraan, meminta part, dan melaporkan selesai atau tunda kepada Register.', bagian: [
    ['Melihat pekerjaan', 'Buka <b>Performa Mekanik</b> dan lihat bagian pekerjaan saat ini. Motor yang diberikan Register akan muncul bersama nomor polisi, tipe, keluhan, dan rincian yang tersedia. Satu mekanik menangani satu motor berstatus Dikerjakan.'],
    ['Memeriksa pekerjaan sebelum mulai', 'Cocokkan nomor polisi dengan motor fisik, baca keluhan, cek KM dan kondisi awal, lalu pastikan part yang dibutuhkan sudah diminta. Jika data kendaraan salah, jangan mengubah sembarangan; laporkan kepada Register.'],
    ['Meminta sparepart', 'Sampaikan kode/nama part dan jumlah kepada bagian Sparepart. Bagian Sparepart membuat order pada WO yang benar. Jika part tidak tersedia, minta Register menerima laporan tunda dengan alasan yang jelas.'],
    ['Laporan selesai', 'Jika motor selesai dikerjakan, lapor kepada Register secara langsung atau melalui prosedur internal bengkel. Register yang menekan <b>Motor selesai</b>. Setelah laporan diterima, status berubah Selesai, nomor antrean dipanggil di TV, dan Anda dapat menerima pekerjaan lain.'],
    ['Laporan tunda', 'Jika pekerjaan belum bisa dilanjutkan, lapor kepada Register beserta alasan spesifik: menunggu part, menunggu persetujuan, menunggu konsumen, atau alasan teknis. Register wajib mengisi alasan dan menekan <b>Lanjut lama (tunda)</b>.'],
    ['Melanjutkan pekerjaan', 'Jika motor ditunda lalu part atau persetujuan sudah tersedia, minta Register membuka tab Ditunda dan memilih mekanik yang akan melanjutkan. Jangan mengerjakan WO yang statusnya masih Ditunda tanpa pengaktifan kembali.'],
    ['Performa dan penghasilan', 'Menu Performa Mekanik menampilkan pekerjaan selesai, nilai jasa, dan waktu kerja. Menu Penghasilan Saya menampilkan gaji/insentif yang diterbitkan. Tunda tidak dihitung sebagai waktu kerja aktif.'],
    ['Absensi', 'Gunakan Absensi Saya untuk scan QR datang dan pulang. Pastikan status berhasil tersimpan sebelum meninggalkan layar. Jika QR gagal, laporkan waktu kejadian kepada admin, jangan meminjam akun mekanik lain.']
  ]},
  sparepart: { judul: 'Sparepart', ringkas: 'Order untuk WO, pembelian supplier, stok cabang, transfer, permintaan barang, dan stok opname.', bagian: [
    ['Order part untuk servis', 'Buka <b>Order Sparepart</b>, pilih motor/WO di daftar kiri, tulis permintaan mekanik, cari kode atau nama part, isi jumlah, lalu tambah. Perhatikan kolom ready karena part yang sudah dipesan WO lain tidak dihitung sebagai stok bebas.'],
    ['Menyimpan order', 'Setelah semua item benar, tekan <b>Simpan order</b> atau <kbd>F2</kbd>. Tunggu indikator berubah menjadi <b>✓ Tersimpan</b>. Part belum dipotong dari stok saat order; stok dipotong ketika pembayaran servis diterima.'],
    ['Rincian part di Register', 'Setelah order tersimpan, Register dapat melihat kode, nama, jumlah, stok, dan nilai part pada bagian <b>Rincian part</b>. Jika salah WO, hapus dari order yang benar lalu simpan ulang.'],
    ['Stok Part', 'Buka <b>Stok Part</b> untuk mencari kode/nama, melihat stok, harga beli, harga jual, kategori, stok menipis, dan kartu stok. Gunakan filter agar tidak perlu memuat semua data saat mencari.'],
    ['Menambah part baru', 'Di Stok Part pilih <b>Part baru</b>, isi kode unik, nama, kategori, harga beli, harga jual, dan stok awal bila diizinkan. Simpan dan tunggu pesan berhasil. Jika salah ketik, ubah data; penghapusan part hanya untuk super admin dengan verifikasi password dan masuk log aktivitas.'],
    ['Pembelian supplier', 'Buka <b>Pembelian Stok → Invoice baru</b>. Isi tanggal, nomor invoice, supplier, status pembayaran, jatuh tempo, serta item dan harga beli. Simpan draft. Saat barang datang, buka <b>Preview & terima barang</b>, cocokkan fisik, lalu masukkan ke stok.'],
    ['Transfer antar cabang', 'Di <b>Stok Part → Transfer</b>, pilih cabang tujuan, tambahkan part dan jumlah, periksa, lalu kirim. Pengirim membuat BAST dari riwayat transfer; penerima memeriksa fisik kemudian menekan <b>Terima</b>.'],
    ['BAST transfer stok', 'Buka riwayat transfer, tekan <b>BAST</b>, periksa nomor transfer, cabang asal/tujuan, item, jumlah, pengirim, penerima, catatan, dan status. Tekan <b>Print / Simpan PDF</b> atau <b>Unduh PDF</b>. BAST dapat dipakai sebagai dokumen serah terima internal.'],
    ['Permintaan antar cabang', 'Jika stok cabang sendiri kurang, gunakan <b>Cek Stok → Minta kirim</b>. Cabang pemilik membuka <b>Permintaan masuk</b>, lalu memilih Kirim atau Tolak dengan alasan. Setelah barang tiba, cabang peminta wajib menekan <b>Terima</b>.'],
    ['Stok opname', 'Buka <b>Stok Opname → Mulai opname</b>, hitung fisik per kode, isi jumlah sebenarnya, dan ajukan. Super admin memeriksa selisih lalu menyetujui atau menolak. Jangan mengubah stok manual untuk menutupi selisih.'],
    ['Export data stok', 'Gunakan <b>Export Excel</b> untuk analisis. File dapat berisi semua cabang, total per cabang, dan sheet masing-masing cabang. Filter Excel berdasarkan kolom cabang atau kategori.']
  ]},
  admin: { judul: 'Admin / Kepala Cabang', ringkas: 'Mengawasi operasional, memperbaiki data sesuai izin, memeriksa laporan, dan membantu semua bagian.', bagian: [
    ['Rutinitas awal hari', 'Buka Beranda, periksa motor aktif, mekanik kosong/sibuk, stok menipis, permintaan transfer, kas, dan notifikasi persetujuan. Pastikan layar TV serta perangkat absensi aktif.'],
    ['Rutinitas akhir hari', 'Pastikan semua motor memiliki status yang benar, order part tersimpan, motor selesai sudah dilaporkan Register, pembayaran tidak tertinggal, kas ditutup, dan permintaan transfer ditindaklanjuti.'],
    ['Membantu Register', 'Admin dapat membuka Registrasi, mencari WO, memeriksa data konsumen/kendaraan, memperbaiki data, mengatur tipe/mekanik, menerima laporan Selesai/Tunda, dan mencetak BAST. Untuk KM lebih kecil, wajib menulis catatan alasan.'],
    ['Membatalkan pendaftaran', 'Gunakan hanya untuk pendaftaran ganda atau salah daftar yang belum dibayar. Periksa nomor WO, nomor antrean, part yang sudah dipesan, dan alasan. Konfirmasi penghapusan karena data servis, layar, dan cek konsumen ikut terpengaruh.'],
    ['Konsumen dan kendaraan', 'Gunakan menu <b>Konsumen & Kendaraan</b> untuk mencari, memperbaiki, menggabungkan data konsumen ganda, memindahkan motor ke pemilik yang benar, melihat log perubahan, dan mencetak daftar konsumen. Selalu tulis alasan untuk koreksi kepemilikan.'],
    ['Persetujuan perangkat layar absensi', 'Jika ada perangkat baru, cocokkan kode yang tampil di perangkat dengan permintaan di menu <b>Persetujuan</b>. Setujui hanya perangkat milik cabang. Cabut perangkat yang hilang atau tidak dikenal.'],
    ['Master Data yang dikelola admin', 'Admin biasanya mengatur tipe motor dan layar TV. Harga jasa, tarif KSG, rekening, mekanik, petugas, insentif, cabang, logo, tema, dan hak akses dapat dibatasi untuk super admin sesuai konfigurasi.'],
    ['Laporan dan Insight', 'Gunakan Laporan Penjualan untuk memeriksa omzet, nota, metode pembayaran, part terlaris, laba part, kasir, mekanik, dan cabang. Insight Konsumen membantu menemukan konsumen yang lama tidak datang.'],
    ['Backup dan perubahan versi', 'Sebelum perubahan besar, pastikan backup tersedia. Setelah rilis aplikasi baru, minta pengguna menekan <b>Update aplikasi</b> (bilah kiri bawah) bila tampilan lama masih terlihat; tombol ini mengosongkan salinan aplikasi di perangkat lalu memuat versi baru tanpa menghapus data. Jangan menghapus data Firebase untuk memperbaiki masalah tampilan.']
  ]},
  super: { judul: 'Super Admin / Pemilik', ringkas: 'Keamanan, master data, persetujuan, cabang, payroll, backup, dan audit.', bagian: [
    ['Keamanan akun utama', 'Gunakan email dan password super admin hanya untuk pemilik/penanggung jawab. Jangan menyimpan password di komputer kasir. Setelah selesai, keluar akun. Tindakan sensitif harus dilakukan sendiri dan tidak didelegasikan dengan membagikan password.'],
    ['Master jasa dan harga', 'Buka <b>Master Data → Jasa Servis</b>. Tambahkan, ubah, aktifkan/nonaktifkan, atau hapus jasa sesuai kebijakan. Perubahan harga baru berlaku pada transaksi berikutnya; data lama menyimpan rincian harga saat transaksi.'],
    ['Master Tarif KSG', 'Buka <b>Master Data → Tarif KSG</b>. Isi nilai klaim per tipe motor untuk KSG ke-1 sampai ke-4. Kosongkan jika tidak ada klaim. Pastikan tipe motor dan tarif sesuai dokumen main dealer karena nilai ini masuk laporan klaim dan penghasilan mekanik.'],
    ['Mekanik dan petugas', 'Atur nama, peran, cabang, akun PIN, dan reset PIN. Jangan menggunakan nama yang sama untuk dua orang. Saat petugas keluar, nonaktifkan aksesnya dan jangan hanya mengganti nama akun lama tanpa mempertimbangkan histori.'],
    ['Rekening dan cabang', 'Isi rekening transfer yang benar dan data cabang, termasuk nama, alamat, nomor telepon/WA, serta pengaturan layar. Data cabang dipakai pada nota, laporan, transfer, dan komunikasi konsumen.'],
    ['Hak akses menu', 'Buka <b>Master Data → Hak Akses Menu</b>. Centang hanya menu yang diperlukan tiap peran. <b>Chat Internal</b> harus dicentang per peran agar muncul (bawaan tidak aktif). Kotak ringkasan Beranda per peran juga diatur di sini. Panduan selalu dapat dibuka dan tidak dapat dimatikan. Perubahan langsung berlaku di perangkat yang sedang login tanpa perlu keluar-masuk. Uji dengan akun peran terkait setelah menyimpan.'],
    ['Publish aturan & index versi 5.19.0', 'Setelah update ke 5.19.0: <b>1.</b> Firebase Console → Firestore → Rules: tempel isi <b>firestore.rules</b> terbaru lalu Publish (menambah koleksi <code>presence</code> untuk status Online/Sibuk/Offline; setiap petugas hanya boleh menulis status miliknya dan wajib memakai jam server). <b>2.</b> Deploy <b>firestore.indexes.json</b> (index <code>chat</code>: ruang + tgl menurun, dan participantEmails + ruang + tgl menurun) melalui Firebase CLI <code>firebase deploy --only firestore:indexes</code> atau buat manual di Console → Indexes. Tunggu status index <b>Enabled</b>. Tanpa langkah 1, semua petugas tampil Offline; tanpa langkah 2, Chat tetap jalan memakai cara lama.'],
    ['Biaya baca/tulis status online', 'Setiap perangkat yang membuka aplikasi menulis 1 dokumen status setiap 2,5 menit selama layar terlihat (±190 tulis per petugas per 8 jam kerja). Status orang lain hanya dibaca saat menu Chat sedang dibuka, sehingga beban baca tetap kecil. Jika kuota Firebase gratis mendekati batas, minta petugas menutup tab aplikasi yang tidak dipakai.'],
    ['Persetujuan pembatalan nota', 'Periksa nota, konsumen, total, metode bayar, alasan, dan dampak stok. Setujui hanya jika alasan sah. Jika menolak, pastikan kasir memahami koreksi yang harus dilakukan.'],
    ['Persetujuan stok opname', 'Bandingkan hasil fisik, selisih, nilai rupiah, riwayat kartu stok, pembelian, transfer, dan transaksi. Setujui hanya setelah penyebab selisih dipahami. Persetujuan akan menyesuaikan stok.'],
    ['Absensi dan payroll', 'Menu Absensi Karyawan untuk rekap dan koreksi manual dengan catatan. Menu Penghasilan Karyawan untuk gaji, insentif, potongan, slip, dan penguncian periode. Setelah periode dikunci, koreksi harus terdokumentasi.'],
    ['THR dan bonus', 'Buat periode THR/bonus, atur persen dan tambahan, periksa masa kerja/pro-rata, tinjau per karyawan, lalu <b>Kunci & terbitkan</b>. Setelah terbit, slip muncul pada Penghasilan Saya dan total masuk pengeluaran sesuai alur.'],
    ['Backup data', 'Buat backup JSON secara berkala dan simpan di lokasi aman yang tidak dapat diakses semua petugas. Uji bahwa file dapat dibaca. Pemulihan data adalah tindakan besar; lakukan hanya setelah memastikan file, periode, dan dampak pemulihan.'],
    ['Log aktivitas dan penghapusan part', 'Penghapusan part memerlukan verifikasi password super admin dan dicatat pada log aktivitas. Sebelum menghapus, pastikan part tidak dipakai WO, nota, pembelian, atau laporan. Lebih aman menonaktifkan data daripada menghapus jika masih memiliki histori.']
  ]},
  troubleshooting: { judul: 'Masalah umum & solusi', ringkas: 'Langkah pemeriksaan sebelum meminta bantuan admin atau dukungan teknis.', bagian: [
    ['Aplikasi loading terus', 'Sejak 5.19.0 aplikasi terbuka paling lama ±3,5 detik setelah login walau sebagian data belum datang; data menyusul otomatis. Jika roda gigi tetap berputar lebih dari 15 detik: tekan <b>Update aplikasi</b> di layar login atau bilah kiri (mengosongkan salinan lama dan memuat ulang). Periksa koneksi internet, muat ulang sekali, lalu tunggu beberapa detik. Jika hanya /pos yang loading, buka dengan alamat resmi <b>www.amuservice.id/pos</b>, bukan file lama/bookmark lama. Jika masih gagal, catat jam, akun/peran, perangkat, dan screenshot error; jangan menghapus data browser sebelum data offline penting dipastikan tersinkron.'],
    ['Data tidak muncul setelah disimpan', 'Pastikan pesan berhasil muncul, periksa cabang aktif, hapus filter pencarian, dan muat ulang. Jika part/WO dibuat di cabang lain, gunakan filter atau pindah cabang sesuai hak akses. Jangan menyimpan berulang-ulang karena dapat membuat data ganda.'],
    ['Menu tertentu lama terbuka', 'Menu yang mengambil data periode lama (Laporan rentang panjang, Insight, Penghasilan, Klaim KSG, Performa Mekanik periode lalu) memang membaca data dari server pada pembukaan pertama. Pembukaan berikutnya dalam 60 detik memakai simpanan sementara sehingga instan. Pilih rentang tanggal secukupnya. Di Insight, tombol <b>Muat seluruh database kendaraan</b> memang berat; gunakan hanya bila perlu.'],
    ['Tampilan belum berubah setelah update', 'Tekan <b>Update aplikasi</b> sekali dan tunggu halaman memuat ulang sendiri. Jika aplikasi dipasang di HP, tutup aplikasi sepenuhnya lalu buka lagi. Pastikan nomor versi di bilah kiri bawah sudah <b>5.19.0</b>.'],
    ['Semua petugas tampil Offline di Chat', 'Status Online membutuhkan aturan Firestore terbaru. Minta Super Admin publish ulang <b>firestore.rules</b> versi 5.19.0. Pastikan juga petugas lain sedang membuka aplikasi (status Offline otomatis bila tidak ada aktivitas lebih dari 6 menit) dan tidak memilih <b>Offline</b> di tombol status.'],
    ['Menu Chat tidak muncul atau pesan tidak tampil', 'Menu Chat hanya tampil bila peran Anda dicentang di <b>Master Data → Hak Akses Menu</b>. Jika menu ada tetapi pesan kosong, periksa koneksi internet lalu tekan Update aplikasi. Pesan yang gagal dikirim akan dikembalikan ke kotak tulisan sehingga bisa dikirim ulang.'],
    ['Tidak ada bunyi saat pesan masuk', 'Pastikan <b>Bunyi notifikasi pesan baru</b> di Chat dicentang dan volume perangkat tidak senyap. Browser kadang menahan suara sampai Anda menyentuh/klik halaman sekali setelah dibuka. Bunyi hanya untuk pesan dari orang lain di ruang Umum atau chat pribadi Anda.'],
    ['Gagal memuat data atau query/index', 'Catat teks error lengkap dan URL yang tampil. Jangan menekan link indeks Firebase tanpa arahan super admin/developer. Sampaikan menu, peran, cabang, dan waktu kejadian agar query dapat diperbaiki dengan aman.'] ,
    ['Membatalkan pesanan sebelum bayar', 'Jika konsumen batal sebelum membayar, bagian Sparepart membuka menu <b>Pesanan Part Pribadi</b>, memilih pesanan, lalu menekan <b>Batal beli</b>. Alasan wajib diisi. Status berubah menjadi dibatalkan; tidak dibuat nota penjualan, tidak ada pengurangan kas, dan tidak ada pemotongan stok penjualan. Lembar cetak lama harus disimpan atau diberi tanda batal agar tidak dipakai ke Kasir.'],
    ['Retur setelah pembayaran', 'Jika barang sudah dibayar tetapi kemudian terbukti memang harus diretur, buka nota part di Kasir/Laporan lalu tekan <b>Ajukan retur</b>. Isi alasan, terima dan periksa barang, lalu kirim pengajuan. Nota asli tidak dihapus. Pengajuan menunggu pemeriksaan dan persetujuan super admin.'],
    ['Persetujuan retur dan pengembalian dana', 'Super admin memeriksa barang, nota, jumlah, alasan, dan bukti. Setelah yakin, pilih <b>Setujui & kembalikan dana</b>, isi catatan, dan konfirmasi password. Sistem mengembalikan stok, mencatat mutasi stok retur, mencatat pengurangan dana dari cash/bank sesuai metode pembayaran asli, menandai nota sebagai retur, dan mengeluarkan nota tersebut dari laporan omzet.'],
    ['Jika retur ditolak atau belum disetujui', 'Selama belum disetujui, stok dan kas/bank belum berubah. Jangan mengembalikan uang secara manual tanpa persetujuan karena saldo kas dan laporan akan berbeda. Simpan catatan pemeriksaan dan komunikasi dengan konsumen.'],
    ['Pesanan part tidak muncul di Kasir', 'Pastikan bagian Sparepart sudah menekan <b>Simpan pesanan & cetak cek</b> sampai ada pesan berhasil, cabang kedua perangkat sama, dan koneksi internet aktif. Kasir dapat menekan menu lain lalu kembali ke menu pesanan untuk memuat ulang. Jangan membuat pesanan kedua sebelum status pesanan pertama diperiksa.'] ,
    ['Pesanan part dikembalikan', 'Jika Kasir menemukan perbedaan, Kasir menekan <b>Tidak sesuai</b> dan wajib menulis alasan. Bagian Sparepart membuka pesanan berstatus <b>Dikembalikan ke Sparepart</b>, memperbaiki item/jumlah, lalu menyimpan dan mencetak lembar cek baru.'] ,
    ['Kas atau bank tidak sesuai', 'Periksa metode pembayaran pada nota, rekening transfer, kembalian, mutasi setor/tarik, dan pengeluaran pada tanggal yang sama. Jangan mencatat penerimaan penjualan sebagai pengeluaran. Jika kas sudah ditutup, jangan mengubah catatan; minta super admin membuka ulang sesuai prosedur.'],
    ['Part baru tidak terlihat', 'Pastikan kode part unik, simpan sampai pesan berhasil, cek filter kategori/cabang, lalu refresh. Jika part tersimpan tetapi tidak bisa dipakai di order, periksa apakah statusnya aktif dan stok cabang sudah benar.'],
    ['Nomor antrean tidak tampil di TV', 'Pastikan layar TV membuka alamat layar yang benar, perangkat sudah disetujui, internet aktif, cabang layar sesuai, dan Register menekan Selesai. Refresh layar TV hanya setelah memastikan status WO sudah tersimpan.'],
    ['Tidak bisa memilih mekanik', 'Mekanik mungkin sedang berstatus Dikerjakan pada motor lain, tidak aktif, berada di cabang berbeda, atau data belum termuat. Periksa daftar Performa Mekanik dan pilih mekanik yang kosong.'],
    ['Total pembayaran salah', 'Jangan lanjut bayar. Kembali ke Register dan periksa jenis KSB/KSG, KSG ke-berapa, jasa, part, biaya lainnya, diskon, dan status. Setelah diperbaiki, buka ulang halaman pembayaran.'],
    ['BAST tidak bisa dicetak', 'Lengkapi data konsumen, nomor polisi, tipe, jenis layanan, estimasi, tanggal, dan jam. Izinkan pop-up browser untuk domain aplikasi, kemudian tekan Preview BAST lagi. Pada dialog cetak pilih printer atau <b>Save as PDF</b>.'],
    ['QR absensi gagal', 'Pastikan kamera diizinkan, QR belum kedaluwarsa, perangkat berada di lokasi, dan akun memakai HP yang terdaftar. Jika ganti HP atau kamera rusak, minta admin mereset perangkat.'],
    ['Pembayaran transfer belum masuk', 'Jangan menganggap screenshot sebagai bukti final. Periksa rekening dan mutasi. Jika sudah terlanjur salah, jangan membuat nota kedua; catat nomor nota dan ajukan koreksi sesuai prosedur.'],
    ['Kapan meminta bantuan?', 'Minta bantuan admin jika berkaitan dengan data konsumen, status WO, stok, kas, atau akses. Minta bantuan super admin jika berkaitan dengan password utama, pembatalan nota, penghapusan, persetujuan stok opname, hak akses, atau backup. Sertakan nomor WO/nota, cabang, waktu, langkah terakhir, dan pesan error.']
  ]}
};

// Gabungkan topik Sparepart (dulu terdefinisi dua kali sehingga topik harga master & Import Excel tidak tampil)
if (P.sparepartMaster) { P.sparepart.bagian = [...P.sparepartMaster.bagian, ...P.sparepart.bagian]; P.sparepart.judul = 'Sparepart, harga master, dan Import Excel'; delete P.sparepartMaster; }

let pilih = null;
let queryCari = '';
// Urutan tombol topik: Apa yang baru → Umum → Tampilan → Fungsi menu → Chat → topik peran → Masalah umum
const UMUM = ['baru', 'umum', 'tampilan', 'menu', 'chat'];
const bolehLihat = () => st.petugas?.super ? [...UMUM, 'registrasi', 'kasir', 'mekanik', 'sa', 'sparepart', 'sales', 'admin', 'super', 'troubleshooting'] : st.role === 'admin' ? [...UMUM, 'registrasi', 'kasir', 'mekanik', 'sa', 'sparepart', 'sales', 'admin', 'troubleshooting'] : [...UMUM, st.role, 'troubleshooting'];
// Topik "Apa yang baru" dibuka otomatis sekali setelah versi baru terpasang
const barukahDibaca = () => { try { const k = 'amu-panduan-baru', v = localStorage.getItem(k) === APP_VERSION; localStorage.setItem(k, APP_VERSION); return v; } catch (e) { return true; } };
const bersih = x => String(x || '').replace(/<[^>]*>/g, ' ').replace(/&amp;/g, '&').toLowerCase();

function render() {
  const daftar = [...new Set(bolehLihat())].filter(k => P[k]);
  if (!pilih || !daftar.includes(pilih)) pilih = barukahDibaca() ? (st.petugas?.super ? 'umum' : (daftar.includes(st.role) ? st.role : 'umum')) : 'baru';
  const p = P[pilih];
  const q = queryCari.trim().toLowerCase();
  const bagian = p.bagian.filter(([j, isi]) => !q || bersih(j + ' ' + isi).includes(q));
  const hasilSemua = q ? daftar.flatMap(k => P[k].bagian.filter(([j, isi]) => bersih(j + ' ' + isi).includes(q)).map(x => ({ k, x }))) : [];
  const body = q ? (hasilSemua.length ? hasilSemua.map(({ k, x }) => `<li><b>${esc(P[k].judul)} — ${esc(x[0])}</b><div>${x[1]}</div></li>`).join('') : '<li><div class="empty">Tidak ada hasil. Coba kata yang lebih pendek seperti <b>stok</b>, <b>part</b>, <b>KSG</b>, <b>BAST</b>, atau <b>nota</b>.</div></li>') : bagian.map(([j, isi]) => `<li><b>${esc(j)}</b><div>${isi}</div></li>`).join('');
  $('#view').innerHTML = `<div class="panel panduan">
    <div class="row spread no-print"><div><h2 style="margin:0">Pusat Bantuan</h2><div class="small muted">Panduan untuk: <b>${esc(p.judul)}</b> · ${q ? hasilSemua.length + ' hasil pencarian' : p.bagian.length + ' topik'}</div></div><button class="btn sm" type="button" data-act="pd-cetak">🖨 Cetak</button></div>
    <div class="cari-box no-print" style="margin-top:12px"><label class="f" for="pd-q">Cari panduan <span class="small muted">contoh: BAST, KSG, transfer, pembayaran, absensi, loading</span><span class="row" style="gap:6px"><input id="pd-q" value="${esc(queryCari)}" placeholder="Ketik kata atau masalah yang dicari..." autocomplete="off" style="flex:1"><button class="btn" type="button" data-act="pd-clear" ${queryCari ? '' : 'disabled'}>Bersihkan</button></span></label></div>
    <div class="seg no-print" role="group" aria-label="Pilih topik panduan">${daftar.map(k => `<button type="button" data-act="pd-pilih" data-k="${k}" aria-pressed="${k === pilih}">${esc(P[k].pendek || P[k].judul.split(' —')[0].split(' /')[0])}</button>`).join('')}</div>
    ${q ? `<div class="note no-print" style="margin-top:10px">Menampilkan semua hasil yang dapat dilihat oleh peran Anda. Klik <button class="link-btn" type="button" data-act="pd-clear">Bersihkan</button> untuk kembali ke topik <b>${esc(p.judul)}</b>.</div>` : `<h2>${esc(p.judul)}</h2><p class="muted" style="margin:0 0 12px">${esc(p.ringkas)}</p>`}
    <ol class="pd-list">${body}</ol>
    <div class="note no-print" style="margin-top:16px"><b>Jika masih bingung:</b> cari kata kunci di atas. Jika tetap tidak menemukan jawaban, siapkan nomor WO/nota, cabang, akun/peran, waktu kejadian, langkah terakhir, dan pesan error sebelum menghubungi admin.</div>
  </div>`;
  if (q) setTimeout(() => { const el = $('#pd-q'); if (el) { el.focus(); el.setSelectionRange(el.value.length, el.value.length); } }, 0);
}

views.panduan = render;
refreshers.panduan = () => {};
Object.assign(actions, {
  'pd-pilih': el => { pilih = el.dataset.k; queryCari = ''; render(); },
  'pd-clear': () => { queryCari = ''; render(); },
  'pd-cetak': () => window.print()
});

export const PANDUAN = P;

// Pencarian memakai input global agar hasil berubah saat mengetik tanpa tombol tambahan.
document.addEventListener('input', e => {
  if (e.target.id !== 'pd-q') return;
  queryCari = e.target.value;
  render();
});
